		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["For {npc:11053} at {area:3197}, at the end of this guide"] = "Para la {npc:11053} en {area:3197}, al final de esta guía",
		["For {zone:1453}: keep it"] = "Para {zone:1453}: guárdala",
		["Listen to his story"] = "Escucha su historia",
		["Mark {npc:10902} with the {item:12815}"] = "Marca la {npc:10902} con la {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marca la {npc:10903} con la {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marca la {npc:10904} con la {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marca la {npc:10905} con la {item:12815}",
		["Portal to {zone:1438}"] = "Portal a {zone:1438}",
		["Pureheart, Dumah, Valorfist and MacDonnell stand around the middle of the camp, by the flight master."] = "Puracorazón, Dumah, Puño de Valor y MacDonnell están por el centro del campamento, junto al maestro de vuelo.",
		["Radley and Durgen"] = "Radley y Durgen",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Cabalga al norte por el camino hasta el Aserradero Crestanorte; {npc:11610} se esconde en el borde del campamento.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "Cabalga al noroeste hasta {area:2276}, en el borde de {area:2277}.",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones while you wear the {quest:5401} (equip it as a trinket first).\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The {npc:10411} (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts."] = "Los Despellejadores esqueléticos y los Necrófagos esclavizantes merodean por los campos al norte del campamento; toda la Plaga de aquí suelta Piedras de la Plaga mientras lleves la {quest:5401} (equípala antes como abalorio).\nCuidado: estos no-muertos te detectan desde muy lejos, y otros no-muertos cercanos se unen al combate cuando atraes a uno.\nCuidado: el {npc:10411} (3 apariciones, reaparece en 15 min) se vuelve invisible fuera de combate y llama a Gárgolas Ventorroca en cuanto empieza el combate.",
		["The Andorhal watchtowers"] = "Las atalayas de Andorhal",
		["The Scarlet Crusade"] = "La Cruzada Escarlata",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "Los médicos, cazadores, caballeros y magos escarlata patrullan el aserradero y el camino hacia {area:190}.",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "Las tres piezas de la muñeca están en las casas en ruinas de {area:2262}; al recoger una pueden aparecer fantasmas. Combínalas para formar la muñeca.",
		["Underwater"] = "Bajo el agua",
		["{area:190} overlook"] = "Mirador de {area:190}",
		["{area:199} cauldron"] = "Caldera de {area:199}",
		["{area:202} cauldron"] = "Caldera de {area:202}",
		["{area:702} flight master"] = "Maestro de vuelo de {area:702}",
		["{item:12841}: wear the {quest:5401} while you kill"] = "{item:12841}: lleva puesta la {quest:5401} mientras matas",
		["{item:12894}, at the monument"] = "{item:12894}, en el monumento",
		["{npc:10926}'s doll"] = "La muñeca de {npc:10926}",
		["{npc:10927}: keep it for {area:2262}"] = "{npc:10927}: guárdalo para {area:2262}",
		["{npc:11063}'s next task, at {area:2264}, is among Scourge of 57-60: skip it."] = "La siguiente tarea de {npc:11063}, en {area:2264}, está entre la Plaga de nivel 57-60: sáltala.",
		["{npc:11610} hides at the lumber camp's edge."] = "{npc:11610} se esconde al borde del campamento maderero.",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722}, en el {object:2096}",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} es élite de nivel 61",
		["{npc:332}, in SI:7"] = "{npc:332}, en IV:7",
		["{npc:3520}, who walks the canals"] = "{npc:3520}, que pasea por los canales",
		["{npc:4217}, upstairs"] = "{npc:4217}, arriba",
		["{object:175924}, in the farmhouse; inside"] = "{object:175924}, en la casa de la granja; dentro",
		["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210}, en {area:2268}: guárdala",
		["{zone:1455} flight master"] = "Maestro de vuelo de {zone:1455}",
		["{zone:1455} has no druid trainer"] = "{zone:1455} no tiene instructor de druidas",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Below ground"] = "Bajo tierra",
		["Bronzebeard's Encampment"] = "Campamento Barbabronce",
		["From the hold, west into the sands: Dredge Crushers dig there; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "Desde el bastión, al oeste hacia las arenas: allí excavan los trituradores de arrastre; los tenazarios Latigosólido, los desolladores y los acechadores de piedra cazan en las mismas arenas.",
		["Hand him the ten texts you kept"] = "Entrégale los diez textos que guardaste",
		["Havunth's camp sits just west of {area:3425}.\nCareful: Havunth is level 60: clear his camp first and fight him at full health."] = "El campamento de Havunth está justo al oeste de {area:3425}.\nCuidado: Havunth es de nivel 60: limpia primero su campamento y lucha contra él con la salud completa.",
		["Into {zone:1451}"] = "Hacia {zone:1451}",
		["Level 60"] = "Nivel 60",
		["Ride back south-east to the hermit."] = "Vuelve al sureste hasta el ermitaño.",
		["Ride back south-west to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "Cabalga de vuelta al suroeste hasta la torre de {area:2742} en {area:2738}; súbela y mata a los emboscadores que surgen por el objeto incrustado.",
		["Ride north along the west side to Mayna's small camp.\nCareful: Mayna is level 60: clear her camp first and fight her at full health."] = "Cabalga al norte por el lado oeste hasta el pequeño campamento de Mayna.\nCuidado: Mayna es de nivel 60: limpia primero su campamento y lucha contra ella con la salud completa.",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand south-east of the camp, where Deathclasp, an elite scorpid, patrols: grab it while he is away."] = "Cabalga al suroeste hasta el campamento enano cerca de las montañas del sur e interroga a {npc:15171} y {npc:15170}. La cartera de {npc:15190} está en la arena, al sureste del campamento, donde patrulla Pinzamorten, un escórpido élite: cógela cuando se aleje.",
		["Ten more for {quest:8323}"] = "Diez más para {quest:8323}",
		["The hermit hides among the rocks south-east of {area:2738}."] = "El ermitaño se esconde entre las rocas al sureste de {area:2738}.",
		["The {area:2742} tower"] = "La torre de {area:2742}",
		["The {area:3098}"] = "El {area:3098}",
		["Twilight Tablet Fragments"] = "Fragmentos de tablilla ({item:20378})",
		["Twilight's Hammer cultists"] = "Cultores del Martillo Crepuscular",
		["{npc:15183}: the tablet fragments come from the Twilight dig"] = "{npc:15183}: los fragmentos de tablilla salen de la excavación Crepuscular",
		["{npc:15189}, upstairs"] = "{npc:15189}, en el piso de arriba",
		["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp.\nCareful: You lose the Silithyst if you mount, stealth, use {spell:642}, {spell:5384} or Vanish. Blink and {spell:17} do not drop it."] = "{npc:17080} acampa fuera de {area:2743}, la colmena del oeste. Recoge una silitista en uno de los géiseres rojos cercanos y llévala al extractor de la Alianza de su campamento.\nCuidado: pierdes la silitista si montas, entras en sigilo o usas {spell:642}, {spell:5384} o Esfumarse. Traslación y {spell:17} no hacen que la sueltes.",
		["{npc:17082}, at the Alliance tents: for {npc:17080} at {area:2743}"] = "{npc:17082}, en las tiendas de la Alianza: para {npc:17080} en {area:2743}",
} end)()
t.guides["forever/alliance/dwarf/01-dun-morogh"] = (function() return {
		["Back east through {area:131}: {npc:1252} by Eric's campfire takes the {quest:287} report, and {npc:1269} the cogs and gears. The Shaman quest here waits for level 10: a Shaman still short of it finishes on the Ice Claw Bears (7-8), Snow Leopards and Large Crag Boars in the fields just south of {area:131}."] = "Vuelve al este por {area:131}: {npc:1252}, junto a la hoguera de Eric, recoge el informe de {quest:287}, y {npc:1269}, los engranajes. La misión de chamán de aquí requiere nivel 10: si a un chamán aún le falta, que termine con los Osos zarpahelada (7-8), Leopardos de la nieve y Grandes jabalíes del risco en los campos justo al sur de {area:131}.",
		["Back north to {area:77} on the way to the tunnel: {npc:2756} stands by {npc:8416} at its door. Gozwin's camp is in the hills just north-west; the {npc:269075} (level 6) prowls around it."] = "Vuelve al norte hasta {area:77} de camino al túnel: {npc:2756} está junto a {npc:8416}, en su puerta. El campamento de Gozwin está en las colinas justo al noroeste; el {npc:269075} (nivel 6) merodea a su alrededor.",
		["Back north to {npc:257808}'s camp above the tunnel. {npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "Vuelve al norte al campamento de {npc:257808} sobre el túnel. {npc:257808} te da el {item:6636}. Sube a la cima sobre su campamento, bebe el sapta junto a la piedra de espíritu y derrota a la {npc:5893}; después coloca su {item:6655} en el {object:61934}, en lo alto del santuario de la Llama eterna.",
		["Back through the tunnel to {npc:257597}' cave above the farm, then west along the road to {zone:1455}."] = "Vuelve por el túnel a la cueva de {npc:257597} sobre la granja y luego ve al oeste por el camino hasta {zone:1455}.",
		["Back to the {area:136}, the wendigo cave south-west of {area:131} where {npc:271546} camps. Flintfire's shipments lie on the cave floor, {npc:278166} is missing deep inside, and {quest:98326} (level 9) keeps the {item:280426} at the back.\nCareful: Wendigos, Elder Wendigos and Wendigo Shamans (up to level 8) stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks avoids this."] = "Vuelve a {area:136}, la cueva de los wendigos al suroeste de {area:131} donde acampa la {npc:271546}. Los cargamentos de Fuegosílex están en el suelo de la cueva, {npc:278166} ha desaparecido en lo más profundo y {quest:98326} (nivel 9) guarda el {item:280426} al fondo.\nCuidado: los Wendigos, Wendigos ancianos y Wendigos chamanes (hasta nivel 8) están muy juntos dentro de la cueva, así que es fácil atraer a varios a la vez; atráelos de uno en uno con ataques a distancia para evitarlo.",
		["Back to {area:77}"] = "Vuelve a {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Vuelve con {npc:257446} en {area:77}. Te da el {item:6635}: toma el sendero marcado con escombros que sube al oeste desde el sur del valle hasta la piedra de espíritu de la cresta, bebe el sapta a su lado y habla con la {npc:5891}; después lleva su {item:6656} a Teo.",
		["Back to {npc:257597}"] = "Vuelve con {npc:257597}",
		["Below ground"] = "Bajo tierra",
		["Brewnall: kill these as you meet them"] = "Las Birras: mata estos según los encuentres",
		["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "Los Jabalíes del risco y los Osos negros jóvenes recorren los campos desde el campamento de Rumbleshot, al noreste, hasta {area:131} y el depósito: mátalos en el camino de vuelta.",
		["Druid trainer"] = "Instructor de druidas",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "Cada misión de Grif Corazón Salvaje te da una {item:15908}: úsala en la bestia que indica y luego llévale la fusta a la herrería de {area:131}. Los Grandes jabalíes del risco, los Leopardos de la nieve y los Osos zarpahelada recorren los campos justo al sur y al este de {area:131}.",
		["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats. Shamans: the Tunnel Rat Geomancers (level 12-13) here carry the {item:5026}.\nCareful: the Tunnel Rat Geomancers (12-13) cast from range in the narrow tunnels: pull them one at a time."] = "Ve al este por las colinas hasta la mina del extremo norte del lago: las cajas de la Liga de Mineros están en sus túneles, entre más Ratatúneles. Chamanes: los Geománticos Ratatúnel (nivel 12-13) de aquí llevan el {item:5026}.\nCuidado: los Geománticos Ratatúnel (12-13) lanzan hechizos a distancia en los túneles estrechos: atráelos de uno en uno.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen acampa en la cresta que domina {area:134} desde el oeste. Habla con él para usar su visión lejana.",
		["Feather Charms, from the Frostmane Novices"] = "Talismanes de plumas, de los Novicios Peloescarcha",
		["Firewood"] = "Leña",
		["Follow the road east past the depot to {area:138}."] = "Sigue el camino al este pasando el depósito hasta {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Sigue el camino al noreste desde {area:131} hasta el depósito bajo el camino de {zone:1455}.",
		["From the {quest:2997} she gives you"] = "Del {quest:2997} que te da",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Las crías de trol Peloescarcha ({npc:706}) llenan las laderas al sur y al este del campamento de {npc:786}.",
		["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}. The den comes after {area:137}, once its level 8 Elder Wendigos and Shamans are no longer above you."] = "Gretchen acampa justo fuera de {area:136}, la cueva de los wendigos al suroeste de {area:131}. La guarida viene después de {area:137}, cuando sus wendigos ancianos y chamanes de nivel 8 ya no estén por encima de ti.",
		["Heal and fortify {npc:12427}"] = "Sana y fortalece a {npc:12427}",
		["Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake and {area:137}."] = "Los osos zarpahelada, los jabalíes del risco mayores y los leopardos de la nieve recorren las colinas alrededor del lago y de {area:137}.",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Colgantes de oso garrahielo ({item:264356}), de las crías de trol Peloescarcha ({npc:706}) de las laderas sobre el campamento",
		["Inside {area:77}"] = "Dentro de {area:77}",
		["Leper Gnomes wander the {area:133} road north of {area:137} and carry the cogs and gears. {area:135} comes next, in the hills south-west of the village.\nCareful: the Leper Gnomes (8-10) walk the road in twos and threes, and many players died here: pull them one at a time."] = "Los Gnomos parias recorren el camino de {area:133} al norte de {area:137} y llevan los engranajes. Después va {area:135}, en las colinas al suroeste de la aldea.\nCuidado: los Gnomos parias (8-10) van por el camino de dos en dos y de tres en tres, y muchos jugadores han muerto aquí: atráelos de uno en uno.",
		["Level 4 spells"] = "Hechizos de nivel 4",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Los Lobos jóvenes andrajosos recorren la nieve justo al sur de {area:77}.",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "Los Aplastacráneos, Rompehuesos y Emboscadores Mentueso comparten la cantera y las laderas al norte; los Emboscadores sueltan el {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Los Troggs Mentueso y los Troggs Comepiedras fornidos excavan por todo el fondo del valle al sur de {area:77}.",
		["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "Siéntate junto a la hoguera de Eric (escribe /sentarse) y espera al beneficio. Si has aprendido una profesión, Eric también te ofrece su Acampada básica, que se entrega a su instructor: herrería con {npc:1241} y {skill:129} con {npc:2326} en {area:131}, minería e ingeniería en {area:189}.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Los Jabalíes del risco pequeños pastan alrededor del campamento de {npc:714} y por el lado oeste del valle.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Los Leopardos de la nieve y los jabalíes recorren la nieve entre el rancho y la cantera. Herreros: los Lingotes de cobre se obtienen fundiendo {item:2770} o de los proveedores de mercancías.",
		["South down the road past the tunnel post into {area:923}: the Stonesplinter Seers (level 13-14) stand among the troggs in its middle. Stay out of the far south end, where Shamans and Bonesnappers (level 15-16) camp, and keep clear of Headsplitter (15) on his walk. The Seers come with other troggs and cast from range: pull one at a time."] = "Baja al sur por el camino pasando el puesto del túnel hasta {area:923}: los Profetas Rompecantos (nivel 13-14) están entre los troggs del centro. No vayas al extremo sur, donde acampan Chamanes y Rompehuesos (nivel 15-16), y mantente lejos de Partecabezas (15) en su patrulla. Los Profetas van con otros troggs y atacan a distancia: atráelos de uno en uno.",
		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "Baja por el camino al sur hasta {area:144} y termina por el camino las orejas, la carne y el icor. {npc:1340} recorre el camino que atraviesa el pueblo.",
		["The Fire Spirit Stone"] = "La piedra del espíritu de fuego",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "La Infusión de albaza hirviendo dura cinco minutos: ve directamente al norte hasta {npc:836}, dentro de {area:77}.",
		["The boars"] = "Los jabalíes",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "La leña está en la nieve alrededor del lago helado junto al refugio.",
		["The quarry troggs"] = "Los troggs de la cantera",
		["The troggs"] = "Los troggs",
		["The troll cave"] = "La cueva de los trols",
		["The tunnel"] = "El túnel",
		["The {area:133} road"] = "El camino de {area:133}",
		["The {area:2257}"] = "El {area:2257}",
		["The {item:6652}"] = "La {item:6652}",
		["The {object:269} in the basement"] = "El {object:269} del sótano",
		["Tram to {zone:1453}"] = "Tranvía a {zone:1453}",
		["Use the {item:6866} on {npc:6177}"] = "Usa el {item:6866} en {npc:6177}",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Empiezas delante de {area:77}, la sala de piedra del extremo norte del valle. {npc:658} espera fuera de la puerta.",
		["Young wolves"] = "Lobos jóvenes",
		["talk to the trainer"] = "habla con el instructor",
		["{area:131} and the depot"] = "{area:131} y el depósito",
		["{area:77} is on the way north from {npc:786}'s camp to the tunnel: {npc:837}, the priest trainer inside, sends priests of level 5 to {npc:1226} in {area:131}."] = "{area:77} está de camino al norte desde el campamento de {npc:786} hasta el túnel: {npc:837}, el instructor de sacerdotes que hay dentro, envía a los sacerdotes de nivel 5 con {npc:1226} en {area:131}.",
		["{item:13850}: the {object:176785}"] = "{item:13850}: el {object:176785}",
		["{item:277976}, in the camp"] = "{item:277976}, en el campamento",
		["{item:280426}: {quest:98326}, at the back"] = "{item:280426}: {quest:98326}, al fondo",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "El {item:286325} está junto al lago helado, entre los elementales de hielo.",
		["{item:3083}: Leper Gnomes"] = "{item:3083}: Gnomos parias",
		["{item:3084}: Leper Gnomes"] = "{item:3084}: Gnomos parias",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}: Geománticos Ratatúnel",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, junto a la piedra de espíritu",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}, junto a la piedra de espíritu",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}: Profetas Rompecantos",
		["{item:6847}: Dark Iron Spies"] = "{item:6847}: espías Hierro Negro",
		["{npc:10090} in {zone:1455} takes it"] = "La recoge {npc:10090} en {zone:1455}",
		["{npc:1126}: tame it with the {item:15908}"] = "{npc:1126}: domestícalo con la {item:15908}",
		["{npc:11406}: {quest:5639}, his own copy of the letter"] = "{npc:11406}: {quest:5639}, su propia copia de la carta",
		["{npc:1196}: tame it with the {item:15908}"] = "{npc:1196}: domestícalo con la {item:15908}",
		["{npc:1201}: tame it with the {item:15908}"] = "{npc:1201}: domestícalo con la {item:15908}",
		["{npc:1226}, upstairs: {item:16605}"] = "{npc:1226}, en el piso de arriba: {item:16605}",
		["{npc:1226}: heal {npc:12427} south of {area:131}"] = "{npc:1226}: sana a {npc:12427} al sur de {area:131}",
		["{npc:1231}, at the smithy"] = "{npc:1231}, en la herrería",
		["{npc:1241} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1241} la recoge en cuanto tu habilidad de {skill:164} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:12427} kneels wounded on the ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer, on the walk back from Rumbleshot's camp. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12427} está arrodillado y herido en la loma entre dos muros bajos justo al sur de {area:131}, al otro lado del camino del instructor de mascotas de cazador, de vuelta del campamento de Rumbleshot. Lánzale {spell:613} (rango 2) y después {spell:1243}: el rango 1 de {spell:613} no cuenta.",
		["{npc:1252} stands by Eric's campfire in front of the {area:2102}; {npc:1241} is in the cellar west of it. {npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the {spell:8553}."] = "{npc:1252} está junto a la hoguera de Eric delante de {area:2102}; {npc:1241} está en el sótano al oeste. {npc:1373} vigila los barriles de {item:2686} en el sótano de la destilería. Compra una {item:2686} al {npc:1247}, haz clic en el barril vigilado y luego dale la cerveza a {npc:1373} desde su ventana de misión (no hay misión que aceptar); después, usa el {spell:8553} en el barril sin vigilar.",
		["{npc:12738}, next to him"] = "{npc:12738}, a su lado",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}: con tiempo límite, cinco minutos para llegar con {npc:836} en {area:77}",
		["{npc:1573}, the gryphon master in the {object:32372}"] = "{npc:1573}, el maestro de grifos de {object:32372}",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}: solo herreros",
		["{npc:1702} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1702} la recoge en cuanto tu habilidad de {skill:202} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1702}, beside {npc:5392}"] = "{npc:1702}, al lado de {npc:5392}",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965} guarda el túnel de salida del valle, al este de {area:77}; {npc:6782} está a su lado, en la boca.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, en la cantera",
		["{npc:2326} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2326} la recoge en cuanto tu habilidad de {skill:129} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:2326}, inside the distillery"] = "{npc:2326}, dentro de la destilería",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}, dentro de {area:77}",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}: {npc:5873} y tu {item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597} espera en una cueva sobre la granja al noroeste de {area:806}; el sendero de subida empieza detrás de la granja.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {npc:2523}, tu {item:5176} y el {item:263412}",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}: la recoge {npc:257597}, junto a la Puerta Sur",
		["{npc:265813}: for {npc:1241}, in the cellar west of the distillery"] = "{npc:265813}: para {npc:1241}, en el sótano al oeste de la destilería",
		["{npc:265813}: for {npc:1702} at {area:189}"] = "{npc:265813}: para {npc:1702} en {area:189}",
		["{npc:265813}: for {npc:2326} in the {area:2102}"] = "{npc:265813}: para {npc:2326} en {area:2102}",
		["{npc:265813}: for {npc:5392} at {area:189}"] = "{npc:265813}: para {npc:5392} en {area:189}",
		["{npc:4256} works at the {object:32372}'s north end, and {npc:1573} keeps the gryphons in the {object:32372}, where the flight from {area:144} lands."] = "{npc:4256} trabaja en el extremo norte de {object:32372}, y {npc:1573} cuida de los grifos en {object:32372}, donde aterriza el vuelo desde {area:144}.",
		["{npc:460}, inside {area:77}"] = "{npc:460}, dentro de {area:77}",
		["{npc:5392} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5392} la recoge en cuanto tu habilidad de {skill:186} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:5392}, at the depot"] = "{npc:5392}, en el depósito",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} entrena a los guerreros en {object:2100}, cerca de la tienda de Osric; el tranvía desde {zone:1455} llega a {object:28027}, al norte. {npc:6089} y {npc:6090} están juntos junto a {object:2152}. {npc:6090} pelea contigo por su jarra. Si {npc:5480} no te ofrece {quest:1638}, ve directamente con {npc:6089}: te da {quest:1639} sin ella.",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: la recoge {npc:6122} en {zone:1453}",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} espera en el sótano de {object:2164}, en {object:2101}.",
		["{npc:6179}: Redemption"] = "{npc:6179}: Redención",
		["{npc:658}: a rune for {npc:895}"] = "{npc:658}: una runa para {npc:895}",
		["{npc:658}: read the {quest:98581}"] = "{npc:658}: lee la {quest:98581}",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, al lado de {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "El campamento de {npc:714} está en el extremo oeste del valle. La {item:10438} está en la nieve al sur, su cofre junto a la cueva de los trols y su cubo de tornillos al este de la cueva: cógelos al pasar.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} y {npc:12738} acampan en el borde suroeste del valle, bajo la cueva de los trols.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} está dentro de la cueva de los trols al este del campamento de {npc:786}, no en la colina de encima: entra por la boca y sigue el túnel hasta el fondo.",
		["{npc:837}, inside {area:77}"] = "{npc:837}, dentro de {area:77}",
		["{npc:837}, the priest trainer"] = "{npc:837}, el instructor de sacerdotes",
		["{npc:895}, the hunter trainer"] = "{npc:895}, el instructor de cazadores",
		["{npc:916}, the rogue trainer"] = "{npc:916}, el instructor de pícaros",
		["{npc:926}, the paladin trainer"] = "{npc:926}, el instructor de paladines",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, junto al buzón de {object:171524}",
		["{quest:1688}: her choker and The Binding are on {zone:1436}'s east-Elwynn loop"] = "{quest:1688}: su gargantilla y The Binding están en la vuelta por el este de Elwynn de {zone:1436}",
} end)()
t.guides["forever/alliance/gnome/01-dun-morogh"] = (function() return {
		["Back east through {area:131}: {npc:1252} by Eric's campfire takes the {quest:287} report, and {npc:1269} the cogs and gears. The Shaman quest here waits for level 10: a Shaman still short of it finishes on the Ice Claw Bears (7-8), Snow Leopards and Large Crag Boars in the fields just south of {area:131}."] = "Vuelve al este por {area:131}: {npc:1252}, junto a la hoguera de Eric, recoge el informe de {quest:287}, y {npc:1269}, los engranajes. La misión de chamán de aquí requiere nivel 10: si a un chamán aún le falta, que termine con los Osos zarpahelada (7-8), Leopardos de la nieve y Grandes jabalíes del risco en los campos justo al sur de {area:131}.",
		["Back north to {area:77} on the way to the tunnel: {npc:2756} stands by {npc:8416} at its door. Gozwin's camp is in the hills just north-west; the {npc:269075} (level 6) prowls around it."] = "Vuelve al norte hasta {area:77} de camino al túnel: {npc:2756} está junto a {npc:8416}, en su puerta. El campamento de Gozwin está en las colinas justo al noroeste; el {npc:269075} (nivel 6) merodea a su alrededor.",
		["Back north to {npc:257808}'s camp above the tunnel. {npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "Vuelve al norte al campamento de {npc:257808} sobre el túnel. {npc:257808} te da el {item:6636}. Sube a la cima sobre su campamento, bebe el sapta junto a la piedra de espíritu y derrota a la {npc:5893}; después coloca su {item:6655} en el {object:61934}, en lo alto del santuario de la Llama eterna.",
		["Back through the tunnel to {npc:257597}' cave above the farm, then west along the road to {zone:1455}."] = "Vuelve por el túnel a la cueva de {npc:257597} sobre la granja y luego ve al oeste por el camino hasta {zone:1455}.",
		["Back to the {area:136}, the wendigo cave south-west of {area:131} where {npc:271546} camps. Flintfire's shipments lie on the cave floor, {npc:278166} is missing deep inside, and {quest:98326} (level 9) keeps the {item:280426} at the back.\nCareful: Wendigos, Elder Wendigos and Wendigo Shamans (up to level 8) stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks avoids this."] = "Vuelve a {area:136}, la cueva de los wendigos al suroeste de {area:131} donde acampa la {npc:271546}. Los cargamentos de Fuegosílex están en el suelo de la cueva, {npc:278166} ha desaparecido en lo más profundo y {quest:98326} (nivel 9) guarda el {item:280426} al fondo.\nCuidado: los Wendigos, Wendigos ancianos y Wendigos chamanes (hasta nivel 8) están muy juntos dentro de la cueva, así que es fácil atraer a varios a la vez; atráelos de uno en uno con ataques a distancia para evitarlo.",
		["Back to {area:77}"] = "Vuelve a {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Vuelve con {npc:257446} en {area:77}. Te da el {item:6635}: toma el sendero marcado con escombros que sube al oeste desde el sur del valle hasta la piedra de espíritu de la cresta, bebe el sapta a su lado y habla con la {npc:5891}; después lleva su {item:6656} a Teo.",
		["Back to {npc:257597}"] = "Vuelve con {npc:257597}",
		["Below ground"] = "Bajo tierra",
		["Brewnall: kill these as you meet them"] = "Las Birras: mata estos según los encuentres",
		["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "Los Jabalíes del risco y los Osos negros jóvenes recorren los campos desde el campamento de Rumbleshot, al noreste, hasta {area:131} y el depósito: mátalos en el camino de vuelta.",
		["Druid trainer"] = "Instructor de druidas",
		["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats. Shamans: the Tunnel Rat Geomancers (level 12-13) here carry the {item:5026}.\nCareful: the Tunnel Rat Geomancers (12-13) cast from range in the narrow tunnels: pull them one at a time."] = "Ve al este por las colinas hasta la mina del extremo norte del lago: las cajas de la Liga de Mineros están en sus túneles, entre más Ratatúneles. Chamanes: los Geománticos Ratatúnel (nivel 12-13) de aquí llevan el {item:5026}.\nCuidado: los Geománticos Ratatúnel (12-13) lanzan hechizos a distancia en los túneles estrechos: atráelos de uno en uno.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen acampa en la cresta que domina {area:134} desde el oeste. Habla con él para usar su visión lejana.",
		["Feather Charms, from the Frostmane Novices"] = "Talismanes de plumas, de los Novicios Peloescarcha",
		["Firewood"] = "Leña",
		["Follow the road east past the depot to {area:138}."] = "Sigue el camino al este pasando el depósito hasta {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Sigue el camino al noreste desde {area:131} hasta el depósito bajo el camino de {zone:1455}.",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Las crías de trol Peloescarcha ({npc:706}) llenan las laderas al sur y al este del campamento de {npc:786}.",
		["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}. The den comes after {area:137}, once its level 8 Elder Wendigos and Shamans are no longer above you."] = "Gretchen acampa justo fuera de {area:136}, la cueva de los wendigos al suroeste de {area:131}. La guarida viene después de {area:137}, cuando sus wendigos ancianos y chamanes de nivel 8 ya no estén por encima de ti.",
		["Heal and fortify {npc:12427}"] = "Cura y fortalece a {npc:12427}",
		["Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake and {area:137}."] = "Los osos zarpahelada, los jabalíes del risco mayores y los leopardos de la nieve recorren las colinas alrededor del lago y de {area:137}.",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Colgantes de oso garrahielo ({item:264356}), de las crías de trol Peloescarcha ({npc:706}) de las laderas sobre el campamento",
		["Inside {area:77}"] = "Dentro de {area:77}",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Sal de {zone:1453} por la puerta principal. La cascada de {quest:1861} está al suroeste de las puertas, de camino al oeste hacia {zone:1436}: llena {item:7207} al pie de ella.",
		["Leper Gnomes wander the {area:133} road north of {area:137} and carry the cogs and gears. {area:135} comes next, in the hills south-west of the village.\nCareful: the Leper Gnomes (8-10) walk the road in twos and threes, and many players died here: pull them one at a time."] = "Los Gnomos parias recorren el camino de {area:133} al norte de {area:137} y llevan los engranajes. Después va {area:135}, en las colinas al suroeste de la aldea.\nCuidado: los Gnomos parias (8-10) van por el camino de dos en dos y de tres en tres, y muchos jugadores han muerto aquí: atráelos de uno en uno.",
		["Level 4 spells"] = "Hechizos de nivel 4",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Los Lobos jóvenes andrajosos recorren la nieve justo al sur de {area:77}.",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "Los Aplastacráneos, Rompehuesos y Emboscadores Mentueso comparten la cantera y las laderas al norte; los Emboscadores sueltan el {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Los Troggs Mentueso y los Troggs Comepiedras fornidos excavan por todo el fondo del valle al sur de {area:77}.",
		["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "Siéntate junto a la hoguera de Eric (escribe /sentarse) y espera el beneficio. Si has aprendido una profesión, Eric también ofrece su Acampada 101, que recoge su instructor: herrería con {npc:1241} y {skill:129} con {npc:2326} en {area:131}, minería e ingeniería en {area:189}.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Los Jabalíes del risco pequeños pastan alrededor del campamento de {npc:714} y por el lado oeste del valle.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Los Leopardos de la nieve y los jabalíes recorren la nieve entre el rancho y la cantera. Herreros: los Lingotes de cobre se obtienen fundiendo {item:2770} o de los proveedores de mercancías.",
		["South down the road past the tunnel post into {area:923}: the Stonesplinter Seers (level 13-14) stand among the troggs in its middle. Stay out of the far south end, where Shamans and Bonesnappers (level 15-16) camp, and keep clear of Headsplitter (15) on his walk. The Seers come with other troggs and cast from range: pull one at a time."] = "Baja al sur por el camino pasando el puesto del túnel hasta {area:923}: los Profetas Rompecantos (nivel 13-14) están entre los troggs del centro. No vayas al extremo sur, donde acampan Chamanes y Rompehuesos (nivel 15-16), y mantente lejos de Partecabezas (15) en su patrulla. Los Profetas van con otros troggs y atacan a distancia: atráelos de uno en uno.",
		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "Baja al sur por el camino hasta {area:144}, terminando las orejas, la carne y el icor por el camino. {npc:1340} recorre el camino que atraviesa el pueblo.",
		["The Fire Spirit Stone"] = "La piedra del espíritu de fuego",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "La Infusión de albaza hirviendo dura cinco minutos: ve directamente al norte hasta {npc:836}, dentro de {area:77}.",
		["The boars"] = "Los jabalíes",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "La leña está en la nieve alrededor del lago helado junto al refugio.",
		["The quarry troggs"] = "Los troggs de la cantera",
		["The troggs"] = "Los troggs",
		["The troll cave"] = "La cueva de los trols",
		["The tunnel"] = "El túnel",
		["The {area:133} road"] = "El camino de {area:133}",
		["The {area:2257}"] = "El {area:2257}",
		["The {item:6652}"] = "La {item:6652}",
		["The {object:269} in the basement"] = "El {object:269} del sótano",
		["Tram to {zone:1453}"] = "Tranvía a {zone:1453}",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Empiezas delante de {area:77}, la sala de piedra del extremo norte del valle. {npc:658} espera fuera de la puerta.",
		["Young wolves"] = "Lobos jóvenes",
		["talk to the trainer"] = "habla con el instructor",
		["{area:131} and the depot"] = "{area:131} y el depósito",
		["{area:77} is on the way north from {npc:786}'s camp to the tunnel: {npc:837}, the priest trainer inside, sends priests of level 5 to {npc:1226} in {area:131}."] = "{area:77} queda de camino al norte desde el campamento de {npc:786} hasta el túnel: {npc:837}, el instructor de sacerdotes que está dentro, envía a los sacerdotes de nivel 5 con {npc:1226} en {area:131}.",
		["{item:13850}: the {object:176785}"] = "{item:13850}: el {object:176785}",
		["{item:277976}, in the camp"] = "{item:277976}, en el campamento",
		["{item:280426}: {quest:98326}, at the back"] = "{item:280426}: {quest:98326}, al fondo",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "El {item:286325} está junto al lago helado, entre los elementales de hielo.",
		["{item:3083}: Leper Gnomes"] = "{item:3083}: Gnomos parias",
		["{item:3084}: Leper Gnomes"] = "{item:3084}: Gnomos parias",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}: Geománticos Ratatúnel",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, junto a la piedra de espíritu",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}, junto a la piedra de espíritu",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}: Profetas Rompecantos",
		["{npc:1226}, upstairs: {item:16605}"] = "{npc:1226}, en el piso de arriba: {item:16605}",
		["{npc:1226}: heal {npc:12427} south of {area:131}"] = "{npc:1226}: cura a {npc:12427} al sur de {area:131}",
		["{npc:1241} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1241} la recoge en cuanto tu habilidad de {skill:164} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1241}, in the cellar west of the distillery"] = "{npc:1241}, en el sótano al oeste de la destilería",
		["{npc:12427} kneels wounded on the ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer, on the walk back from Rumbleshot's camp. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12427} está arrodillado y herido en la cresta entre dos muros bajos justo al sur de {area:131}, al otro lado del camino del instructor de mascotas de cazador, de vuelta del campamento de Rumbleshot. Lanza {spell:613} (rango 2) sobre él y después {spell:1243}: el rango 1 de {spell:613} no cuenta.",
		["{npc:1252} stands by Eric's campfire in front of the {area:2102}; {npc:1241} is in the cellar west of it. {npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the {spell:8553}."] = "{npc:1252} está junto a la hoguera de Eric delante de {area:2102}; {npc:1241} está en el sótano al oeste. {npc:1373} vigila los barriles de {item:2686} en el sótano de la destilería. Compra una {item:2686} al {npc:1247}, haz clic en el barril vigilado y luego dale la cerveza a {npc:1373} desde su ventana de misión (no hay misión que aceptar); después, usa el {spell:8553} en el barril sin vigilar.",
		["{npc:12738}, next to him"] = "{npc:12738}, a su lado",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}: con tiempo límite, cinco minutos para llegar con {npc:836} en {area:77}",
		["{npc:1573}, the gryphon master in the {object:32372}"] = "{npc:1573}, el maestro de grifos de {object:32372}",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}: solo herreros",
		["{npc:1702} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1702} la recoge en cuanto tu habilidad de {skill:202} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1702}, beside {npc:5392}"] = "{npc:1702}, al lado de {npc:5392}",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965} guarda el túnel de salida del valle, al este de {area:77}; {npc:6782} está a su lado, en la boca.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, en la cantera",
		["{npc:2326} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2326} la recoge en cuanto tu habilidad de {skill:129} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:2326}, inside the distillery"] = "{npc:2326}, dentro de la destilería",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}, dentro de {area:77}",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}: {npc:5873} y tu {item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597} espera en una cueva sobre la granja al noroeste de {area:806}; el sendero de subida empieza detrás de la granja.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {npc:2523}, tu {item:5176} y el {item:263412}",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}: la recoge {npc:257597}, junto a la Puerta Sur",
		["{npc:258785}: {quest:94817}, her own copy of the letter"] = "{npc:258785}: {quest:94817}, su propia copia de la carta",
		["{npc:265813}: for {npc:1241}, in the cellar west of the distillery"] = "{npc:265813}: para {npc:1241}, en el sótano al oeste de la destilería",
		["{npc:265813}: for {npc:1702} at {area:189}"] = "{npc:265813}: para {npc:1702} en {area:189}",
		["{npc:265813}: for {npc:2326} in the {area:2102}"] = "{npc:265813}: para {npc:2326} en {area:2102}",
		["{npc:265813}: for {npc:5392} at {area:189}"] = "{npc:265813}: para {npc:5392} en {area:189}",
		["{npc:4256} works at the {object:32372}'s north end, and {npc:1573} keeps the gryphons in the {object:32372}, where the flight from {area:144} lands."] = "{npc:4256} trabaja en el extremo norte de {object:32372}, y {npc:1573} cuida de los grifos en {object:32372}, donde aterriza el vuelo desde {area:144}.",
		["{npc:460}, inside {area:77}"] = "{npc:460}, dentro de {area:77}",
		["{npc:5392} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:5392} la recoge en cuanto tu habilidad de {skill:186} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:5392}, at the depot"] = "{npc:5392}, en el depósito",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} entrena a los guerreros en {object:2100}, cerca de la tienda de Osric; el tranvía de {zone:1455} llega a {object:28027}, al norte. {npc:6089} y {npc:6090} están juntos junto a {object:2152}. {npc:6090} pelea contigo por su jarra. Si {npc:5480} no te ofrece {quest:1638}, ve directamente con {npc:6089}: te da {quest:1639} sin ella.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} está en la torre de los magos de {object:2101}; te da un frasco para la cascada de {quest:1861}.",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: la recoge {npc:6122} en {zone:1453}",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} espera en el sótano de {object:2164}, en {object:2101}.",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, al lado de {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "El campamento de {npc:714} está en el extremo oeste del valle. La {item:10438} está en la nieve al sur, su cofre junto a la cueva de los trols y su cubo de tornillos al este de la cueva: cógelos al pasar.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} y {npc:12738} acampan en el borde suroeste del valle, bajo la cueva de los trols.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} está dentro de la cueva de los trols al este del campamento de {npc:786}, no en la colina de encima: entra por la boca y sigue el túnel hasta el fondo.",
		["{npc:837}, inside {area:77}"] = "{npc:837}, dentro de {area:77}",
		["{npc:837}, the priest trainer"] = "{npc:837}, el instructor de sacerdotes",
		["{npc:912}, the warrior trainer"] = "{npc:912}, el instructor de guerreros",
		["{npc:916}, the rogue trainer"] = "{npc:916}, el instructor de pícaros",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}, el instructor de magos, dentro de {area:77}",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, junto al buzón de {object:171524}",
		["{quest:1688}: her choker and The Binding are on {zone:1436}'s east-Elwynn loop"] = "{quest:1688}: su gargantilla y The Binding están en la vuelta por el este de Elwynn de {zone:1436}",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "\"Tía\" Bernice Pedregosa",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Vuelve con {npc:6122} el Vinculaoscuro. Usa el {item:6928} en el círculo de invocación del sótano de {object:2164} y derrota al abisario que aparece.",
		["Billy plays in the {area:64}, east of the mine."] = "Billy Maclure juega en {area:64}, al este de la mina.",
		["Chunks of Boar Meat"] = "Trozos de carne de jabalí",
		["Class trainer"] = "Instructor de clase",
		["Crystal Kelp Fronds"] = "Hojas de kelp de cristal",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "Los Zahoríes bribones Defias acampan en las orillas de {area:86}; también sueltan los Pañuelos de lino rojo. {object:56} está en el poblado múrloc de la orilla noreste.\nCuidado: los Zahoríes bribones lanzan hechizos a distancia y un {npc:6866} (10) recorre la orilla con ellos: atráelos de uno en uno.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Los Matones Defias acampan en el claro al este de la abadía y por el lado este del valle.",
		["Druid trainer"] = "Instructor de druidas",
		["Follow the hills south to the tower, on the road west."] = "Sigue las colinas hacia el sur hasta la torre, en el camino al oeste.",
		["Follow the hills south to the tower."] = "Sigue las colinas hacia el sur hasta la torre.",
		["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "Sigue el camino hacia el este pasando {area:91} hasta el puente. Acaba con los Merodeadores y Osos del bosque jóvenes de alrededor del río, al sur del puente.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Sigue el camino hacia el norte desde {area:87} hasta {zone:1453}. {npc:5497} está en el Sagrario del Mago, la torre de {object:2101}; te da un frasco para la cascada de {quest:1861}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Sigue el camino hacia el norte desde {area:87} hasta {zone:1453}. {npc:6122} espera en el sótano de {object:2164}, en {object:2101}.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Sigue el camino hacia el sur, fuera de {area:87}, hasta {area:64}. {npc:251} Maclure espera junto a la casa.",
		["Fun with Elementals: {npc:248464}"] = "Álbum de fotos: diversión con elementales: {npc:248464}",
		["He stands by the river west of the farm."] = "Está junto al río, al oeste de la granja.",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Regresa por {area:87} y hacia el este por el camino hasta {area:62}. {npc:881} (nivel 9) está junto a la granja.",
		["Heal and fortify {npc:12423}"] = "Sana y fortalece a {npc:12423}",
		["Inside {area:34}"] = "Dentro de {area:34}",
		["It lies by the river north-west of the logging camp."] = "Está junto al río, al noroeste del campamento maderero.",
		["Large Candles"] = "Velas grandes",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Sal de {zone:1453} por la puerta principal. La cascada de {quest:1861} está al suroeste de las puertas, de camino al oeste hacia {zone:1436}: llena {item:7207} al pie de ella.",
		["Lost Books: Kobold Miners and Tunnelers"] = "Libros perdidos: Mineros kóbold y Tuneladores",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "Los múrlocs y los Correcorrientes múrloc ocupan la orilla este; los Montones de chatarra están en su campamento. Cuidado: los múrlocs están muy juntos, así que es fácil atraer a dos o tres a la vez en un combate: atráelos de uno en uno desde el borde del campamento y no persigas a ninguno hasta el siguiente grupo.",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "Al noreste del campamento maderero. Los Zahoríes bribones Defias acampan en las orillas del lago.\nCuidado: los Zahoríes bribones lanzan hechizos a distancia y un {npc:6866} (10) recorre la orilla con ellos: atráelos de uno en uno.",
		["Painted Gnoll Armbands"] = "Bandas gnoll pintadas",
		["Red Burlap Bandanas"] = "Arpilleras rojas",
		["Red Linen Bandanas"] = "Pañuelos de lino rojo",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "Los Jabatos Zarparrío y los Avanzados ocupan las colinas al sur del cuartel, a lo largo de la frontera con {zone:1436}.",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Los gnolls Zarparrío acampan en las colinas al oeste de {area:86}; {quest:91725} están en sus campamentos.",
		["She stands by her cart at the vineyard east of the Abbey."] = "Está junto a su carro, en el viñedo al este de la abadía.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Manzanas rojas lustrosas, de {npc:894}, para {quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Siéntate (/sentarse) junto a su hoguera hasta tener {spell:1229451}",
		["South down the road to the {area:64}."] = "Al sur por el camino hasta {area:64}.",
		["Subdue the voidwalker"] = "Somete al abisario",
		["The Defias camp"] = "El campamento Defias",
		["The Fishing Traps sit along the west shore of the lake."] = "Las trampas de pesca ({object:694772}) están en la orilla oeste del lago.",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "La granja Pedregosa está al oeste de la mina. La vieja Pedregosa y la \"Tía\" Bernice están junto a la casa.\nElla está sentada dentro de la casa de la granja.",
		["The bridge"] = "El puente",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it.\nCareful: Elmpaw, a level 12 elite gnoll, walks the woods and hills from the logging camp north to {area:86} and the gnoll camps: keep clear of him when you see him coming."] = "El campamento está al noreste del puente. Los Haces de leña están por el campamento y en el bosque al norte.\nCuidado: Zarpaolmo, un gnoll élite de nivel 12, recorre el bosque y las colinas desde el campamento maderero al norte hasta {area:86} y los campamentos gnoll: apártate de él cuando lo veas venir.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Las cajas de uvas están en los viñedos, detrás de los Defias. {npc:103} espera junto a la cabaña del extremo este del valle.",
		["The gnoll camps"] = "Los campamentos gnoll",
		["The kobold camp"] = "El campamento kóbold",
		["The lake shore"] = "La orilla del lago",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "La mina está al suroeste de los campamentos gnoll. {item:247816} están cerca de la entrada; los Geománticos kóbold ocupan los túneles.\nCuidado: {npc:471} (7-10), las Arañas mineras (7-9) y {npc:248474} (7) son élites del fondo de la mina: atrae a los kóbolds de uno en uno cerca de la entrada y retírate si viene un élite; son más fáciles con un amigo.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "La mina está al oeste de los viñedos. Los Mineros kóbold y los Tuneladores llenan ambos niveles; {npc:248464}, un kóbold con nombre, tiene el álbum de fotos en los túneles inferiores. {npc:248464} es élite: se recomienda ir en grupo.",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too.\nCareful: {npc:276180}, a level 11 rare murloc, walks the river by {npc:261}' bridge, east of the Prowlers' woods: leave him be."] = "Los múrlocs de la orilla este sueltan el kelp. Desolladores: los Lobos grises del bosque recorren el bosque entre el lago y {area:91}; los Merodeadores, más al este, también dan pieles.\nCuidado: {npc:276180}, un múrloc raro de nivel 11, recorre el río junto al puente de {npc:261}, al este del bosque de los Merodeadores: no te metas con él.",
		["The vineyards and {npc:103}"] = "Los viñedos y {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Young Forest Bears on the way; the Prowlers (level 9-10) wait for the walk back to {npc:261}, after the logging camp and the mine. Careful: {npc:248278} is a level 11 elite on the murloc shore. Only go for his head with a group; otherwise leave him: it's optional."] = "La {item:247813}, el Hacha empapada y la Caja de herramientas empapada están en el río al sur del puente. {npc:330}, una jabalina enorme, hoza en {area:62}, al oeste del río, con su {npc:390}: aparta primero a los cerditos. Mata Osos del bosque jóvenes por el camino; los Merodeadores (nivel 9-10) quedan para la vuelta con el {npc:261}, después del campamento maderero y la mina. Cuidado: {npc:248278} es un élite de nivel 11 de la orilla de los múrlocs. Ve a por su cabeza solo en grupo; si no, déjalo: es opcional.",
		["The {quest:91736}"] = "{quest:91736}",
		["Walk into the mine"] = "Entra en la mina",
		["Walk through the mine"] = "Recorre la mina",
		["Wolves"] = "Lobos",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Empiezas delante de la abadía. {npc:823} está al pie de la escalinata; {npc:197}, dentro de la sala; {npc:951} y {npc:247229}, en la biblioteca de la derecha; {npc:196}, fuera, en la esquina noroeste.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Los Lobos jóvenes y los Lobos madereros recorren los campos junto a la abadía.",
		["grind on {npc:1922}"] = "mata {npc:1922} para subir",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "su rastreador de kóbolds muestra los kóbolds en los que hacer clic en el camino a {area:87}",
		["talk to the trainer"] = "habla con el instructor",
		["{item:247824}, from the still"] = "{item:247824}, del alambique",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}: Jabalíes colmillopétreo",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}: {object:83763} del campamento Defias",
		["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423} está arrodillado y herido junto a un árbol en la orilla oeste de {area:18}, entre las trampas de pesca. Lánzale {spell:613} (rango 2) y luego {spell:1243}: el rango 1 de {spell:613} no cuenta. Se marcha cuando recibe ambos y vuelve en unos 3 minutos.",
		["{npc:1632} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1632} la recoge en cuanto tu habilidad de {skill:165} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1632}, beside {npc:6306}"] = "{npc:1632}, junto a {npc:6306}",
		["{npc:1651} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:1651} la recoge en cuanto tu habilidad de {skill:356} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: domestícalo con la {item:15908}",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, el instructor de magos, dentro de la abadía",
		["{npc:2329} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:2329} la recoge en cuanto tu habilidad de {skill:129} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:2329}, in the Lion's Pride Inn"] = "{npc:2329}, en la Posada Orgullo de León",
		["{npc:247229}, in the library; inside"] = "{npc:247229}, en la biblioteca; dentro",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} y {npc:248248} están al pie de la torre.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, junto a la abadía",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} está con los instructores de {area:87}. Cada una de sus misiones te da una {item:15908}: úsala en la bestia que te indique y devuélvele la vara. Los Jabalíes Ocultorroca y los Osos del bosque jóvenes recorren las colinas al sur de {area:64}; los Lobos grises del bosque, el bosque al este de {area:18}.",
		["{npc:253}, back in the inn"] = "{npc:253}, de vuelta en la posada",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, a su lado: {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} vigila el puente del camino al este; {npc:248265} está justo al otro lado.",
		["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}."] = "{npc:263399} acampa al noreste de la posada. Si has aprendido una profesión, también ofrece su Acampada 101, que recibe su instructor: desuello, peletería y pesca en la orilla del lago; {skill:129} y herrería en {area:87}.",
		["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399}: para {npc:1632}, en la orilla del lago",
		["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399}: para {npc:1651}, en la orilla del lago",
		["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399}: para {npc:2329}, en la Posada Orgullo de León",
		["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399}: para {npc:514}, en la herrería de {area:87}",
		["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399}: para {npc:6306}, en la orilla del lago",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: lo recibe {npc:5497}, en {zone:1453}",
		["{npc:375}, the priest trainer"] = "{npc:375}, la instructora de sacerdotes",
		["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}, la instructora de sacerdotes: lo recibe {npc:377}, en {area:87}",
		["{npc:377}, upstairs"] = "{npc:377}, en el piso de arriba",
		["{npc:377}, upstairs: {item:16605}"] = "{npc:377}, en el piso de arriba: {item:16605}",
		["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377}: sana a {npc:12423} en {area:18}",
		["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377}: {npc:376}, en {zone:1453}, la recoge",
		["{npc:459}, outside the Abbey"] = "{npc:459}, fuera de la abadía",
		["{npc:514} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:514} la recoge en cuanto tu habilidad de {skill:164} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:514}, at the smithy across the road"] = "{npc:514}, en la herrería al otro lado del camino",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: domestícalo con la {item:15908}",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: lo recibe {npc:6122}, en {zone:1453}",
		["{npc:6306} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6306} la recoge en cuanto tu habilidad de {skill:393} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:6306}, on the lake shore east of town; inside"] = "{npc:6306}, en la orilla del lago al este del pueblo; dentro",
		["{npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:6306}, {npc:383} y {npc:1651} están en la orilla de {area:18}, al este del pueblo.",
		["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306}: solo desolladores, las pieles se desuellan; dentro",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, junto a los establos al sur de la abadía",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6} excavan en los viñedos al noreste de la abadía. De vez en cuando uno suelta un {quest:91741}: haz clic derecho en él.",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: domestícalo con la {item:15908}",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, de vuelta en la escalinata de la abadía",
		["{npc:911}, the warrior trainer; inside"] = "{npc:911}, el instructor de guerreros; dentro",
		["{npc:915}, the rogue trainer"] = "{npc:915}, el instructor de pícaros",
		["{npc:925}, the paladin trainer"] = "{npc:925}, el instructor de paladines",
		["{npc:952}, upstairs"] = "{npc:952}, en el piso de arriba",
		["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955}: quiere tu {item:247824}; dentro",
		["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}: para {npc:234} en {area:108}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "{object:694855} crece en los campos alrededor de los viñedos y de la granja Pedregosa; los Jabalíes colmillopétreo de alrededor dan la sangre.\nLos Jabalíes colmillopétreo pastan entre los viñedos y la granja.",
		["{quest:76}'s entrance"] = "Entrada de {quest:76}",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it.\nCareful: {npc:248464} (6), a kobold deep in the mine, is elite, and {npc:79} (10, rare) walks the tunnels: pull the kobolds one at a time."] = "{quest:87} está dentro de {area:57}, no en la colina de encima: entra por la boca y ve por la izquierda hasta el fondo de la mina; no subas las escaleras. Los Bandidos Defias de los viñedos sueltan de vez en cuando una {item:1972}: haz clic derecho en ella.\nCuidado: {npc:248464} (6), un kóbold del fondo de la mina, es élite, y {npc:79} (10, raro) recorre los túneles: atrae a los kóbolds de uno en uno.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} y {npc:330}",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/sentarse junto a la hoguera de {npc:265811} hasta que tengas {spell:1229451}",
		["Back at {area:256}"] = "De vuelta en {area:256}",
		["Back to the moonwell."] = "Vuelve al pozo de la luna.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "Vuelve a lo alto de {area:256}. El {object:654846} está a su lado.",
		["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "Vuelve arriba con {npc:3567} con las arañas hechas y el musgo de {npc:272116}.",
		["Befouled Webwoods"] = "Tejemadera infectos",
		["Below ground"] = "Bajo tierra",
		["Bloodfeather harpies"] = "Arpías Plumasangre",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn {area:493}'s flight path from {npc:10897}, south of the lake, for later trips. Then {npc:11800} in {area:2361} flies Druids straight to {area:702} from her gossip: hers is no flight path to learn. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Lanza {spell:18960}. {npc:11802} está en {area:2361}; {quest:5929} está en el bosque al noroeste. Aprende la ruta de vuelo de {area:493} con {npc:10897}, al sur del lago, para viajes futuros. Después, {npc:11800} en {area:2361} lleva a los druidas directamente a {area:702} desde su diálogo: no es una ruta de vuelo que se aprenda. {npc:11802} está en el piso de arriba de su edificio: sube por dentro, la flecha no distingue los pisos.",
		["Crawler Legs: the Tide Crawlers"] = "Patas de reptador: los Corremareas",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Cada misión de Dazalar te da una {item:15908}: úsala en la bestia que nombra y devuélvele la vara en {area:186}. Los rondadores Tejemadera merodean alrededor del poblado; los acechadores sable de la noche y los estridadores estrígidos recorren el bosque al sur.",
		["East along the road to {area:186}."] = "Al este por el camino hasta {area:186}.",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Escolta a {npc:275744} fuera del túmulo; {npc:2081} en {area:186} recibe el informe.",
		["Fandral in {zone:1457} takes it"] = "La recibe Fandral en {zone:1457}",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Los conos inferi están bajo los árboles alrededor de {area:186} y {npc:2150}: recógelos por el camino al este y entrégaselos a {npc:2150} de camino a {npc:7234}.",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442}."] = "Vuela otra vez a {area:702} y toma el portal hasta {npc:4217}; luego vuelve a volar a {area:442}.",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Sigue el camino al suroeste desde {area:188}. {npc:2150} está sentado junto a él, justo al este de {area:186}.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Los emboscadores Tuercepinos se esconden a lo largo del camino al oeste de {area:258}.",
		["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "Los místicos Tuercepinos y {npc:7234} acampan al noreste de {area:260}. {npc:7234} suelta la {item:8049}: ábrela para conseguir la joya.\nCuidado: {npc:7234} espera junto a la hoguera con místicos a su alrededor, así que es difícil atraerlo sin que vengan otros.",
		["Gnarlpine Shamans"] = "Chamanes Tuercepinos",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Vuelve a bajar a {area:702} y vuela a {area:442}. El {object:177525} está en las colinas justo al este del poblado: usa el {item:15208} allí, derrota a Lunaclaw y habla con el {npc:12144}.",
		["Grells (level 2-3) carry {item:3297} in the woods west of the tree, by the totems. The {npc:1989} further north are level 3-4: the Grells by the totems are enough."] = "Los grells (nivel 2-3) llevan {item:3297} en el bosque al oeste del árbol, junto a los tótems. Los {npc:1989} más al norte son de nivel 3-4: con los grells de los tótems basta.",
		["Heal and fortify {npc:12429}"] = "Cura y fortalece a {npc:12429}",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Sal de {area:188} por el sendero al sureste de {area:256}: {npc:6780} está a su lado, donde baja hacia el camino a {area:186}.",
		["Level 12 spells while you're in the Temple of the Moon: the priest trainers stand beside {npc:11401}."] = "Hechizos de nivel 12 ya que estás en el Templo de la Luna: los instructores de sacerdotes están junto a {npc:11401}.",
		["Level 12 spells while you're in the {area:1658}: the hunter, rogue and druid trainers all stand in it."] = "Hechizos de nivel 12 ya que estás en {area:1658}: los instructores de cazadores, pícaros y druidas están todos allí.",
		["Level 12 spells while you're on the {area:1660}: the warrior trainers stand beside {quest:1684}."] = "Hechizos de nivel 12 ya que estás en {area:1660}: los instructores de guerreros están junto a {quest:1684}.",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "Los sables de la Noche sarnosos y los jabalíes Cardo deambulan al norte de {area:256}, camino de la cueva. {npc:1994} está al fondo. {npc:8584} espera entre los árboles al oeste de la entrada de la cueva.",
		["Nightsabers"] = "Sables de la Noche",
		["North to {area:257}"] = "Al norte, hacia {area:257}",
		["North-east from Ursal's den, back to {area:186}. {npc:6094} takes a {item:159} with the fronds and the vial: if you drank yours, buy another from {npc:6736} in this inn before you hand in."] = "Al noreste desde la guarida de Ursal, de vuelta a {area:186}. {npc:6094} pide un {item:159} junto con las frondas y el vial: si te bebiste el tuyo, compra otro a {npc:6736} en esta posada antes de entregar.",
		["North-west of Dolanaar, on the way to the {area:264}, Befouled Webwoods creep through the woods; {npc:272116} prowls at their east edge and carries the {item:281023}.\n{npc:272116} is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own."] = "Al noroeste de Dolanaar, camino del {area:264}, los Tejemadera infectos merodean por el bosque; {npc:272116} ronda por su borde este y lleva el {item:281023}.\n{npc:272116} es élite (nivel 12): se recomienda ir en grupo. Despeja primero las arañas a su alrededor y atráelo a él solo.",
		["On the way back south to the glade: {npc:272046} (level 12) flies on the slopes north-west of the moonwell, among Bloodfeather Matriarchs (11). Pull the harpies around her first."] = "De vuelta al sur hacia el claro: {npc:272046} (nivel 12) vuela por las laderas al noroeste del pozo de la luna, entre Matriarcas Sangrepluma (11). Atrae primero a las arpías de su alrededor.",
		["Priest trainer"] = "Instructor de sacerdotes",
		["Sentinel Arynia again"] = "Centinela Arynia otra vez",
		["South from the glade to the road: Shayla walks the road west of {area:186}, from where the path down from the glade meets it south-west to the bend at about 38,54 and back."] = "Al sur desde el claro hasta el camino: Shayla recorre el camino al oeste de {area:186}, desde donde lo cruza el sendero que baja del claro, al suroeste hasta la curva en torno a 38,54, y vuelta.",
		["South of the pools. The {object:6751} grows by the Hold; the furbolgs around it drop the rest of the fangs.\nCareful: the Gnarlpine Avengers (9-10) and Augurs here stand close together and many players died at the Hold: pull them one at a time."] = "Al sur de las charcas. La {object:6751} crece junto al bastión; los fúrbolgs de alrededor sueltan el resto de los colmillos.\nCuidado: los Vengadores Tuercepinos (9-10) y los Augures están muy juntos y muchos jugadores han muerto en el bastión: atráelos de uno en uno.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "Al sureste de Dolanaar, hasta {npc:2080}. Los brotes azotadores deambulan a su alrededor en la orilla.",
		["South-west from {area:259}, past the {area:478}: Ursal prowls the far south of the island.\nCareful: Gnarlpine of roughly level 9-11 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."] = "Al suroeste desde {area:259}, pasando {area:478}: Ursal ronda el extremo sur de la isla.\nCuidado: fúrbolgs Tuercepinos de nivel 9-11 aproximadamente llenan el campamento y están muy juntos, así que es fácil atraer a varios a la vez. Acaba con ellos de uno en uno antes de enfrentarte a Ursal.",
		["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "Al suroeste de Brisa Estelar, al sur de {npc:2150}. {npc:2080} cuida sus arbolitos en la orilla; los brotes azotadores y los brezomaderas deambulan a su alrededor, y los {quest:919} crecen entre ellos.",
		["South-west of the barrow. The moonwell sits by the pools."] = "Al suroeste del túmulo. El pozo de la luna está junto a las charcas.",
		["Speak with the {quest:5929}"] = "Habla con el {quest:5929}",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Toma otra vez el camino al noroeste desde {area:186}; sigue tendida a su lado, camino de {zone:1457}.",
		["The WANTED poster outside the inn"] = "El cartel de SE BUSCA a la puerta de la posada",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms. Its furbolgs drop Shayla's fangs.\nCareful: the barrow's Gnarlpine Defenders, Augurs and Shamans (7-9) stand in threes in the narrow tunnels: pull each group back toward the entrance before you go deeper."] = "El túmulo está al sur del camino. {npc:275744} está retenida dentro, {npc:7317} duerme en lo más hondo y los cuatro cofres de reliquias están en las salas inferiores. Sus fúrbolgs sueltan los colmillos de Shayla.\nCuidado: los Defensores, Augures y Chamanes Tuercepinos (7-9) del túmulo están en grupos de tres en los túneles estrechos: atrae cada grupo hacia la entrada antes de adentrarte más.",
		["The grells west of the tree"] = "Los grells al oeste del árbol",
		["The moonwell"] = "El pozo de la luna",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "El pozo de la luna está en el centro del claro. La {object:6752} crece en su extremo norte.",
		["The road to {zone:1457}"] = "El camino a {zone:1457}",
		["The {area:478}"] = "El {area:478}",
		["The {object:177525}"] = "El {object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "Los {object:4406} están al fondo de {area:257}: toma el sendero central, luego a la izquierda donde se divide, hasta la cornisa alta. Los grells sueltan champiñones jacinto; los lirios alunados crecen junto a las charcas al norte de {area:256}.",
		["The {object:6752} grows at the glade's north end, on the way: then north along the island's northern edge by {area:266}, {npc:7319}, a level 12 spider, lurks."] = "La {object:6752} crece en el extremo norte del claro, de camino; luego al norte por el borde norte de la isla junto a {area:266}, donde acecha {npc:7319}, una araña de nivel 12.",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Los corremareas corretean por la orilla bajo el pueblo; {quest:983} está en la playa, justo al sur de los muelles. Los trilladores de la Costa Oscura nadan en las aguas poco profundas. {object:175207} yace en la orilla, justo al sur del pueblo.",
		["Use the {item:18152} at the moonwell"] = "Usa la {item:18152} en el pozo de la luna",
		["Use the {item:5185} at the moonwell"] = "Usa la {item:5185} en el pozo de la luna",
		["Use the {item:5619} at the moonwell"] = "Usa la {item:5619} en el pozo de la luna",
		["Use the {item:5621} at the moonwell"] = "Usa la {item:5621} en el pozo de la luna",
		["Walk Lynessa out and keep her alive"] = "Saca a Lynessa y mantenla con vida",
		["Warrior trainer"] = "Instructor de guerreros",
		["Webwood Lurkers"] = "Rondadores Tejemadera",
		["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "Al oeste por el camino hacia la ciudad. Shayla recorre este tramo del camino, desde la flecha al suroeste hasta la curva en torno a 38,54, y vuelta: si no está en la flecha, sigue el camino al suroeste. Todos los fúrbolg Tuercepinos sueltan colmillos: cuentan los emboscadores de este camino, los del túmulo y los de {area:261}.",
		["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors.\nCareful: {npc:272116}, a level 12 elite, prowls the east edge of the Befouled Webwoods north-west of {area:186}: if you are alone, keep clear of the webwoods and go round him."] = "Al oeste desde las arañas hasta {area:265}, y luego al norte a lo largo del río hasta el claro: los fustales de sus orillas sueltan los Tumores musgosos.\nCuidado: {npc:272116}, un élite de nivel 12, ronda el borde este de los Tejemadera infectos al noroeste de {area:186}: si vas solo, mantente lejos de las arañas y rodéalo.",
		["With a profession learned, {npc:265811} also offers its Camping 101, which its trainer takes: alchemy and herbalism beside {npc:6286}, {skill:129} with {npc:6094} in the inn, skinning and leatherworking at the Maneweavers' camp on the road west."] = "Con una profesión aprendida, {npc:265811} también ofrece su Acampada 101, que recibe su instructor: alquimia y herboristería junto a {npc:6286}, {skill:129} con {npc:6094} en la posada, desuello y peletería en el campamento de los Tejecrín, en el camino al oeste.",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Empiezas al pie de {area:256}, el gran árbol de {area:188}.",
		["Young Nightsabers and Young Thistle Boars (level 1-2) roam around {area:256}: start with them. The Gnarlpine Totems stand in the woods west of the tree, where the Grells (2-3) roam: take them once the beasts are done."] = "Los Sables de la noche jóvenes y los Jabalíes cardo jóvenes (nivel 1-2) deambulan alrededor de {area:256}: empieza por ellos. Los Tótems Tuercepinos están en el bosque al oeste del árbol, donde rondan los grells (2-3): ve a por ellos cuando acabes con las bestias.",
		["talk to the trainer"] = "habla con el instructor",
		["{area:1658} trainers"] = "Instructores de {area:1658}",
		["{area:186} again"] = "{area:186} otra vez",
		["{area:258}'s mouth"] = "Entrada de {area:258}",
		["{area:702} flight master"] = "Maestro de vuelo de {area:702}",
		["{area:736}, outside the barrow"] = "{area:736}, fuera del túmulo",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "{item:159} de {npc:6736}, para {npc:6094}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "{item:3371} de {npc:3614}, junto a {npc:6094}",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}, en el Templo de la Luna: Fragmentos estelares",
		["{npc:12429} kneels wounded on the rocks at the north edge of {area:259}, on the walk back to {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count. She runs off once both land and is back in about 5 minutes."] = "{npc:12429} está arrodillada y herida en las rocas del borde norte de {area:259}, camino de vuelta a {area:186}, sin marca de misión encima. Lánzale {spell:613} (rango 2) y luego {spell:1243}: el rango 1 de {spell:613} no cuenta. Se marcha en cuanto recibe ambos y vuelve en unos 5 minutos.",
		["{npc:1992}, south of the tree"] = "{npc:1992}, al sur del árbol",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: domestícalo con la {item:15908}",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: domestícalo con la {item:15908}",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038} espera dentro de la cueva, abajo o arriba en la cornisa; ve por la derecha.",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: domestícalo con la {item:15908}",
		["{npc:2077}, by the path"] = "{npc:2077}, junto al sendero",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}: un sigilo para {npc:3596}",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: la recibe {quest:922} en {zone:1457}",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082}, en la rampa del árbol",
		["{npc:2150} sits by the road just east of {area:186}, between {area:186} and {area:260}."] = "{npc:2150} está sentado junto al camino, justo al este de {area:186}, entre {area:186} y {area:260}.",
		["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151} patrulla el camino al oeste de la aldea: si no está en la flecha, sigue el camino hasta encontrarla.",
		["{npc:2151}, on the road west of the village"] = "{npc:2151}, en el camino al oeste del poblado",
		["{npc:265811}, by the campfire"] = "{npc:265811}, junto a la hoguera",
		["{npc:265811}: for {npc:3603}, beside {npc:6286}"] = "{npc:265811}: para {npc:3603}, junto a {npc:6286}",
		["{npc:265811}: for {npc:3604}, beside {npc:6286}"] = "{npc:265811}: para {npc:3604}, junto a {npc:6286}",
		["{npc:265811}: for {npc:3605}, by the road west"] = "{npc:265811}: para {npc:3605}, junto al camino al oeste",
		["{npc:265811}: for {npc:6094} in the inn"] = "{npc:265811}: para {npc:6094}, en la posada",
		["{npc:265811}: for {npc:6287}, by the road west"] = "{npc:265811}: para {npc:6287}, junto al camino al oeste",
		["{npc:272034} and {npc:272044}"] = "{npc:272034} y {npc:272044}",
		["{npc:272034} and {npc:272044} (level 10) fly just west of the moonwell. {npc:272046} (12) waits further north for the walk back from {npc:7319}."] = "{npc:272034} y {npc:272044} (nivel 10) vuelan justo al oeste del pozo de la luna. {npc:272046} (12) espera más al norte, para la vuelta desde {npc:7319}.",
		["{npc:3514}, at the top of the tree"] = "{npc:3514}, en lo alto del árbol",
		["{npc:3515}, south of the inn"] = "{npc:3515}, al sur de la posada",
		["{npc:3516}, in the {area:1658}"] = "{npc:3516}, en el {area:1658}",
		["{npc:3519}, by the moonwell"] = "{npc:3519}, junto al pozo de la luna",
		["{npc:3567}: {quest:932}'s Befouled Webwoods and the elite {npc:272116}'s moss, on the walk to the {area:264}"] = "{npc:3567}: los Tejemadera infectos de {quest:932} y el musgo del élite {npc:272116}, camino del {area:264}",
		["{npc:3593}, the warrior trainer; inside"] = "{npc:3593}, el instructor de guerreros; dentro",
		["{npc:3594}, the rogue trainer"] = "{npc:3594}, el instructor de pícaros",
		["{npc:3595}, the priest trainer, on the second level of {area:256} on the way down: {npc:3600} in {area:186} takes it"] = "{npc:3595}, el instructor de sacerdotes, en el segundo nivel de {area:256} al bajar: la recibe {npc:3600} en {area:186}",
		["{npc:3595}, the priest trainer: in at the tree's front entrance and up the ramp"] = "{npc:3595}, el instructor de sacerdotes: entra por la puerta principal del árbol y sube por la rampa",
		["{npc:3596}, the hunter trainer"] = "{npc:3596}, el instructor de cazadores",
		["{npc:3597}, the druid trainer at {area:256}"] = "{npc:3597}, el instructor de druidas en {area:256}",
		["{npc:3600}: heal {npc:12429} by {area:259}"] = "{npc:3600}: cura a {npc:12429} junto a {area:259}",
		["{npc:3600}: {npc:11401} in {zone:1457} takes it"] = "{npc:3600}: la recibe {npc:11401} en {zone:1457}",
		["{npc:3602}: {npc:4217} in {zone:1457} takes it"] = "{npc:3602}: la recibe {npc:4217} en {zone:1457}",
		["{npc:3603} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3603} la recoge en cuanto tu habilidad de {skill:171} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:3603}, beside {npc:6286}"] = "{npc:3603}, junto a {npc:6286}",
		["{npc:3604} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3604} la recoge en cuanto tu habilidad de {skill:182} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:3604}, beside {npc:6286}"] = "{npc:3604}, junto a {npc:6286}",
		["{npc:3605} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:3605} la recoge en cuanto tu habilidad de {skill:165} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:3605}, beside {npc:6287}"] = "{npc:3605}, junto a {npc:6287}",
		["{npc:3649}, north end of the village"] = "{npc:3649}, en el extremo norte del pueblo",
		["{npc:4092}, in the Temple of the Moon"] = "{npc:4092}, en el Templo de la Luna",
		["{npc:4146} in {zone:1457} takes it"] = "La recibe {npc:4146} en {zone:1457}",
		["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146}, en el {area:1658}: {spell:5149}",
		["{npc:4217}, in the {area:1658}"] = "{npc:4217}, en el {area:1658}",
		["{npc:6094} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6094} la recoge en cuanto tu habilidad de {skill:129} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:6094}, in the inn"] = "{npc:6094}, en la posada",
		["{npc:6287} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "{npc:6287} la recoge en cuanto tu habilidad de {skill:393} llegue a 20: recolecta o fabrica hasta entonces, la guía sigue mientras tanto.",
		["{npc:6287}, camped beside the road before Shayla"] = "{npc:6287}, acampado junto al camino antes de Shayla",
		["{npc:7318} (level 10), {npc:7317}'s soulless body, walks around {area:736} in the den: kill him, then use {npc:7317}'s {item:8149}."] = "{npc:7318} (nivel 10), el cuerpo sin alma de {npc:7317}, recorre {area:736} en la guarida: mátalo y luego usa el {item:8149} de {npc:7317}.",
		["{npc:7999}, above {npc:4092}"] = "{npc:7999}, encima de {npc:4092}",
		["{npc:8583}, east of the tree"] = "{npc:8583}, al este del árbol",
		["{object:673378}, just west of the moonwell"] = "{object:673378}, justo al oeste del pozo de la luna",
		["{quest:917} and the antidote"] = "{quest:917} y el antídoto",
		["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979}: lanza {spell:1259799} y Fusión de las Sombras, y luego entrégasela a {npc:3595}",
} end)()
t.guides["forever/alliance/nightelf/02-darkshore"] = (function() return {
		["Back north-east into the mountains to the crystal."] = "Vuelve al noreste, a las montañas, hasta el cristal.",
		["Bears and the Blackwood camp"] = "Osos y el campamento Bosquenegro",
		["Blackwood furbolgs"] = "Furbolgs Bosquenegro",
		["Class trainer"] = "Instructor de clase",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Sube a las montañas orientales al este de {area:447}; el {object:175524} está en una cornisa.",
		["Crawler Legs: the Tide Crawlers"] = "Patas de reptador: los Corremareas",
		["Druid trainer"] = "Instructor de druidas",
		["Fill the tube at the moonwell in the village"] = "Llena el tubo en el pozo de la luna del pueblo",
		["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "Sigue la costa hacia el sur, más allá de {area:447}: una {quest:4728} yace en la orilla al oeste del Páramo y otra más al sur, cerca de {area:450}. Otros tres restos yacen más al suroeste entre Oráculos Brumagris y Cazamareas Brumagris (18-20): la guía los deja para la última vuelta, cuando estés más cerca de su nivel.",
		["Grell Earrings"] = "Pendientes grell",
		["Highborne Relics"] = "Reliquias de Altonato",
		["Moonstalker Fangs"] = "Colmillos de Acechalunas",
		["Only if you still carry {quest:983}'s quest: the Tide Crawlers scuttle along the shore below the village, and {quest:983} stands on the beach just south of the docks."] = "Solo si aún llevas la misión de {quest:983}: los Corremareas corretean por la orilla bajo el pueblo, y {quest:983} está en la playa, justo al sur de los muelles.",
		["Read the {object:17188}"] = "Lee {object:17188}",
		["Read the {object:17189}"] = "Lee {object:17189}",
		["The WANTED poster outside the inn"] = "El cartel de SE BUSCA a la puerta de la posada",
		["The beach"] = "La playa",
		["The red crystal"] = "El cristal rojo",
		["The skeletal turtle"] = "La tortuga esquelética",
		["The southern beaches"] = "Las playas del sur",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Los corremareas corretean por la orilla bajo el pueblo; {quest:983} está en la playa, justo al sur de los muelles. Los trilladores de la Costa Oscura nadan en las aguas poco profundas. {object:175207} yace en la orilla, justo al sur del pueblo.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "Te perdiste esto en la visita anterior de la ruta a esta zona: ahora va primero. Es rápido y abre las misiones que le siguen.\nEl barco atraca al oeste del pueblo. El maestro de vuelo está en la colina al sur de la posada; los que dan misiones están repartidos por la calle principal.",
		["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289}, en la playa al oeste de los muelles; bajo el agua",
		["{item:12349}, at the waterfall"] = "{item:12349}, en la cascada",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: Sátiros Deth'ryll",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} está en el borde norte de las ruinas. Altonatos malditos, Altonatos en pena y {npc:2178} las recorren; el fantasma de {npc:3667} camina entre ellos y el búho {npc:270196} vuela en círculos al este. Las dos tablillas están en las ruinas; una {quest:4722} yace en la orilla al oeste.",
		["{npc:3644}, on the pier"] = "{npc:3644}, en el muelle",
		["{npc:3649}, north end of the village"] = "{npc:3649}, en el extremo norte del pueblo",
		["{npc:3666}, upstairs in the inn"] = "{npc:3666}, en el piso de arriba de la posada",
} end)()
t.guides["forever/alliance/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "Usa /sentarse junto a la hoguera de {npc:263664} hasta obtener {spell:1229451}",
		["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Los rastreatormentas y soldados de a pie Al'Aketh acampan justo al norte de {npc:257944} y sueltan la reliquia; los chilladores al oeste de ella sueltan las plumas y las garras; el {item:265105} crece junto al arroyo al oeste de ella.",
		["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "De vuelta en {quest:92529}: los clamatormentas y {npc:251662} llenan el pueblo, los clamatormentas llevan los suministros robados y {npc:251966} está en el extremo sur.",
		["Back to the Hermit"] = "Vuelve con el ermitaño",
		["Back to {area:16622}"] = "Vuelve a {area:16622}",
		["Bandit Highwaymen"] = "Bandidos salteadores",
		["Below ground"] = "Bajo tierra",
		["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {zone:1436}."] = "Bolvar Fordragon está en la sala del trono de {object:2117}, en el extremo norte de la ciudad. Luego sal por la puerta principal hacia {zone:1436}.",
		["Cast {spell:1259705} at the {object:460002}"] = "Lanza {spell:1259705} sobre la línea ley",
		["Class trainer"] = "Instructor de clase",
		["Desperate times"] = "Tiempos desesperados",
		["Druid trainer"] = "Instructor de druidas",
		["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Ábrete paso al norte hasta {area:16629}. Guardianes, clamaespíritus y maestros del acero defienden el acceso; {npc:253576} espera en la puerta del santuario, y {npc:253590}, dentro del sanctasanctórum.",
		["Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "El campamento de Fillion está al noroeste, y las matriarcas chilladoras anidan justo al oeste del campamento.",
		["Find {npc:258130}"] = "Encuentra a {npc:258130}",
		["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "Sigue el camino al sur hasta {area:16624}. {npc:263664} acampa junto al fuego al oeste del pueblo; {npc:251523} y {npc:251903} están en el centro.",
		["For {npc:234} at {area:108}"] = "Para {npc:234} en {area:108}",
		["Head north into {area:16631}. {npc:257944} camps in its east."] = "Ve al norte hacia {area:16631}. {npc:257944} acampa en su parte este.",
		["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them.\nThe Novice Seers practise in the clearing west of Shen'dar, on the way back to the village."] = "Ve al noroeste hasta los nidos de hipogrifo de los acantilados occidentales. El {item:263493} está alrededor de los nidos; la matriarca patrulla entre ellos.\nLos Videntes novicios practican en el claro al oeste de Shen'dar, de camino de vuelta al pueblo.",
		["Heal the injured druids in the Nightfang Den"] = "Cura a los druidas heridos de la Guarida Colmillo Nocturno",
		["Highlands Bandits"] = "Bandidos de las Tierras Altas",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Sal de {zone:1453} por la puerta principal. La cascada de {quest:1861} está al suroeste de las puertas, de camino al oeste hacia {zone:1436}: llena el {item:7207} en su base.",
		["Level 14 spells while you're in {zone:1453}: warriors and rogues train in {object:2100}, hunters in the {object:28027}, mages in the Wizard's Sanctum of the {object:2101}. Druids train with {npc:5504} below."] = "Hechizos de nivel 14 ya que estás en {zone:1453}: los guerreros y pícaros entrenan en {object:2100}, los cazadores en {object:28027} y los magos en el Sagrario del Mago de {object:2101}. Los druidas entrenan con {npc:5504}, más abajo.",
		["Level 14 spells while you're with {npc:5504}."] = "Hechizos de nivel 14 ya que estás con {npc:5504}.",
		["Level 4 spells"] = "Hechizos de nivel 4",
		["Listen to {npc:252448}'s story"] = "Escucha la historia de {npc:252448}",
		["Listen to {npc:257554}"] = "Escucha a {npc:257554}",
		["Meet {npc:253844} at the gate"] = "Reúnete con {npc:253844} en la puerta",
		["North of the cones: the Wind Hollows drift around the refugees' camp, the {item:266433} lie between the tents, and {npc:259013} lies at its north end."] = "Al norte de las piñas: los huecos ventosos flotan alrededor del campamento de refugiados, las {item:266433} están entre las tiendas y {npc:259013} yace en su extremo norte.",
		["North-west of Valanaar along the road, past {npc:273017}: the dead cultist lies just north of him."] = "Al noroeste de Valanaar, siguiendo el camino, pasado {npc:273017}: el cultor muerto yace justo al norte de él.",
		["On the road south-east to {area:16638}, {npc:273017} watches the {quest:98512} just north of him.\nCareful: the {quest:98512} (9-10) stand close together: pull them one at a time."] = "En el camino al sureste hacia {area:16638}, {npc:273017} vigila a los {quest:98512} justo al norte de él.\nCuidado: los {quest:98512} (9-10) están muy juntos: atráelos de uno en uno.",
		["Prideclaws and Galestriders"] = "Garramanadas y zancavendavales",
		["Prideclaws and Galestriders roam the grasslands around the village. Galestriders drop both the eggs and the meat: most players get the eggs from the ones just west of the village."] = "Las garramanadas y los zancavendavales rondan los pastizales alrededor del pueblo. Los zancavendavales sueltan tanto los huevos como la carne: la mayoría de jugadores consigue los huevos de los que hay justo al oeste del pueblo.",
		["Priest trainer"] = "Instructor de sacerdotes",
		["Raw Windstones and the {npc:251404}"] = "Piedras de viento en bruto y la {npc:251404}",
		["Ripe Stormapples and Hungry Bandits are in the orchard by the farm, {quest:92683} in the fields north-east of it, Ornery Galestriders all around. The {npc:250929} stands in the field north-east of the farm."] = "Las manzanas tempestuosas maduras y los bandidos hambrientos están en el huerto junto a la granja, {quest:92683} en los campos al noreste, y los zancavendavales malhumorados por todas partes. El {npc:250929} está en el campo al noreste de la granja.",
		["Search the dead cultist"] = "Registra al cultor muerto",
		["Search the wardrobe"] = "Registra el armario",
		["Shen'dar turn-ins"] = "Entregas en Shen'dar",
		["Skyhoppers"] = "Saltanubes",
		["Skyhoppers swarm the fields west of {area:16638}."] = "Los saltanubes pululan por los campos al oeste de {area:16638}.",
		["Standing our ground"] = "Nos mantenemos firmes",
		["Tame it with the {item:15908}"] = "Domestícalo con la {item:15908}",
		["Tame {npc:254588}"] = "Domestica un {npc:254588}",
		["Tell {npc:252800} you're ready"] = "Dile a {npc:252800} que estás listo",
		["The Bandit Highwaymen hold the hills north of the farm."] = "Los bandidos salteadores ocupan las colinas al norte de la granja.",
		["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp.\nCareful: the bandits stand in close groups and players often died in this camp: pull them one at a time from the edge."] = "Los Bandidos de las Tierras Altas acampan al noreste del pueblo. \"Malabrisa\" Bennic espera en el extremo norte de su campamento.\nCuidado: los bandidos están en grupos muy juntos y muchos jugadores han muerto en este campamento: atráelos de uno en uno desde el borde.",
		["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "Las piedras de viento en bruto brillan en el suelo justo al sur de la arboleda. {quest:92463} revolotea sobre el prado más al este, de camino a {npc:249363}.",
		["The Windstone Formations"] = "Las formaciones de piedras de viento",
		["The Windstone Formations stand on the rise west of Fillion's camp."] = "Las formaciones de piedras de viento están en la loma al oeste del campamento de Fillion.",
		["The bounty board"] = "El tablón de recompensas",
		["The class trainers stand together in the grove"] = "Los instructores de clase están juntos en la arboleda",
		["The dead cultist"] = "El cultor muerto",
		["The eastern watchtower"] = "La atalaya oriental",
		["The missing scholar"] = "El erudito desaparecido",
